INSERT INTO stock_balances (sku,warehouse_id,qty) SELECT sku,warehouse_id,SUM(CASE WHEN kind='in' THEN qty WHEN kind='out' THEN -qty ELSE qty END)::int FROM stock_movements WHERE warehouse_id='00000000-0000-0000-0000-000000000c03'::uuid GROUP BY sku,warehouse_id ON CONFLICT (sku,warehouse_id) DO UPDATE SET qty=EXCLUDED.qty,updated_at=NOW();
